static uint8_t *buf;
static size_t pos;
static uint32_t rd32(void) { uint32_t v; memcpy(&v, buf + pos, 4); pos += 4; return v; }
static uint16_t rd16(void) { uint16_t v; memcpy(&v, buf + pos, 2); pos += 2; return v; }
static uint8_t  rd8(void)  { return buf[pos++]; }
static float    rdf(void)  { float v; memcpy(&v, buf + pos, 4); pos += 4; return v; }

// Uploads an RGBA texture (nearest filtering). Cut-out textures get coverage-preserving mipmaps.
static void tex_upload(GLuint id, int w, int h, const uint8_t *data) {
    glBindTexture(GL_TEXTURE_2D, id);
        glTexImage2D(GL_TEXTURE_2D, 0, GL_RGBA, w, h, 0, GL_RGBA, GL_UNSIGNED_BYTE, data);
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_NEAREST);
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_REPEAT);
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_REPEAT);
        if (mip_has_cutout(data, w * h)) {
            // cut-out texture: coverage-preserving mips, picked per-pixel with no blending (keeps the PS1 look,
            // removes the shimmer / vanishing of thin rails and bars at a distance)
            float target = mip_coverage(data, w * h, 1.f);
            uint8_t *a = malloc((size_t)w * h * 4), *b = malloc((size_t)w * h * 4);
            memcpy(a, data, (size_t)w * h * 4);
            {   // edge_colour: see-through and half-see-through texels carry whatever colour the exporter left behind (often bright); the cut-out edge
                // then shows it as a bright rim. Their colour is replaced by the average of the solid texels around them (alpha is untouched).
                for (int y = 0; y < h; y++) for (int x = 0; x < w; x++) {
                    const uint8_t *s = data + ((size_t)y * w + x) * 4; if (s[3] >= 250) continue;
                    for (int rr = 1; rr <= 4; rr++) {
                        int n = 0, sr = 0, sg = 0, sb = 0;
                        for (int dy = -rr; dy <= rr; dy++) for (int dx = -rr; dx <= rr; dx++) {
                            if (dx > -rr && dx < rr && dy > -rr && dy < rr) continue;
                            int xx = x + dx, yy = y + dy; if (xx < 0 || yy < 0 || xx >= w || yy >= h) continue;
                            const uint8_t *q = data + ((size_t)yy * w + xx) * 4; if (q[3] < 250) continue;
                            sr += q[0]; sg += q[1]; sb += q[2]; n++;
                        }
                        if (n) { uint8_t *d = a + ((size_t)y * w + x) * 4; d[0] = (uint8_t)(sr / n); d[1] = (uint8_t)(sg / n); d[2] = (uint8_t)(sb / n); break; }
                    }
                }
                glTexImage2D(GL_TEXTURE_2D, 0, GL_RGBA, w, h, 0, GL_RGBA, GL_UNSIGNED_BYTE, a);
            }
            int cw = w, ch = h, lvl = 0;
            while (cw > 1 || ch > 1) {
                int nw, nh;
                mip_next(a, cw, ch, b, &nw, &nh, target);
                lvl++;
                glTexImage2D(GL_TEXTURE_2D, lvl, GL_RGBA, nw, nh, 0, GL_RGBA, GL_UNSIGNED_BYTE, b);
                uint8_t *t = a; a = b; b = t; cw = nw; ch = nh;
            }
            free(a); free(b);
            glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_NEAREST_MIPMAP_NEAREST);
        } else {
            glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_NEAREST);   // PS1: no filtering
        }
}

// ---- culling: frustum planes from the view-projection matrix, and a sphere test (+ fog distance: past FOG_END everything is fog colour = the clear colour)
static void frustum_planes(const float *pv, float pl[6][4]) {
    for (int k = 0; k < 6; k++) {
        int axis = k >> 1; float sg = (k & 1) ? -1.0f : 1.0f;
        for (int c = 0; c < 4; c++) pl[k][c] = pv[c * 4 + 3] + sg * pv[c * 4 + axis];
        float l = sqrtf(pl[k][0]*pl[k][0] + pl[k][1]*pl[k][1] + pl[k][2]*pl[k][2]);
        if (l > 1e-8f) for (int c = 0; c < 4; c++) pl[k][c] /= l;
    }
}
static int sph_visible(float cx, float cy, float cz, float r, const float pl[6][4], float ex, float ey, float ez, float fwx, float fwy, float fwz) {
    float dx = cx - ex, dy = cy - ey, dz = cz - ez;
    if (dx*fwx + dy*fwy + dz*fwz - r > FOG_END) return 0;
    for (int k = 0; k < 6; k++) if (pl[k][0]*cx + pl[k][1]*cy + pl[k][2]*cz + pl[k][3] < -r) return 0;
    return 1;
}
static int inst_visible(const Instance *I, const Drawable *d, const float pl[6][4], float ex, float ey, float ez, float fwx, float fwy, float fwz) {
    const float *m = I->m;
    float cx = m[0]*d->bc[0] + m[4]*d->bc[1] + m[8]*d->bc[2] + m[12];
    float cy = m[1]*d->bc[0] + m[5]*d->bc[1] + m[9]*d->bc[2] + m[13];
    float cz = m[2]*d->bc[0] + m[6]*d->bc[1] + m[10]*d->bc[2] + m[14];
    float s0 = m[0]*m[0] + m[1]*m[1] + m[2]*m[2], s1 = m[4]*m[4] + m[5]*m[5] + m[6]*m[6], s2 = m[8]*m[8] + m[9]*m[9] + m[10]*m[10];
    float sc = sqrtf(s0 > s1 ? (s0 > s2 ? s0 : s2) : (s1 > s2 ? s1 : s2));
    float r = d->br * sc + 0.05f;
    float dx = cx - ex, dy = cy - ey, dz = cz - ez;
    if (dx*fwx + dy*fwy + dz*fwz - r > FOG_END) return 0;                  // the shader's fog distance is view depth: past FOG_END it is pure fog colour
    for (int k = 0; k < 6; k++) if (pl[k][0]*cx + pl[k][1]*cy + pl[k][2]*cz + pl[k][3] < -r) return 0;
    return 1;
}
static uint32_t g_cull_drawn, g_cull_total;
static float g_fpl_prev[6][4]; static int g_fpl_ok; static unsigned g_frame_ctr;      // last frame's view frustum: enemies behind you or off-screen are not skinned


static void maplog(const char *fmt, const char *a, const char *b);
#define LVL_POOL (3584u * 1024u)
static uint8_t *g_lvl_pool; static int g_lvl_pool_tried;      /* lvl_pool: the level file is read into a block that is set aside once, at the first map load while the heap is still clean (a 2 MB malloc failed on a fragmented heap and killed the map change) */
static uint8_t *lvl_alloc(long sz) {
    if (!g_lvl_pool_tried) { g_lvl_pool_tried = 1; g_lvl_pool = malloc(LVL_POOL); }
    if (g_lvl_pool && (unsigned long)sz <= LVL_POOL) return g_lvl_pool;
    return malloc(sz);
}
static void lvl_free(uint8_t *p) { if (p && p != g_lvl_pool) free(p); }
static int load_level(const char *path) {
    FILE *f = fopen(path, "rb");
    if (!f) return 0;
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    { char t_[64]; snprintf(t_, sizeof t_, "%ld bytes", sz); maplog("load: level file %s%s", t_, ""); }
    buf = lvl_alloc(sz);
    if (!buf) { maplog("load: level file ALLOC FAILED%s%s", "", ""); fclose(f); return 0; }
    { size_t got_ = fread(buf, 1, sz, f); for (int try_ = 0; got_ != (size_t)sz && try_ < 3; try_++) { maplog("load: level file short read, retrying%s%s", "", ""); fseek(f, 0, SEEK_SET); got_ = fread(buf, 1, sz, f); } if (got_ != (size_t)sz) { maplog("load: level file READ FAILED%s%s", "", ""); lvl_free(buf); buf = NULL; fclose(f); return 0; } }
    fclose(f);
    if (memcmp(buf, "BBL2", 4) != 0) { lvl_free(buf); return 0; }     // old BBL1 files: re-run the converter
    pos = 4;
    nTex = rd32(); nGeom = rd32(); nDraw = rd32(); nInst = rd32();
    uint32_t nCol = rd32();
    spawnX = rdf(); spawnY = rdf(); spawnZ = rdf();
    {
        ColTri *ct = malloc((nCol ? nCol : 1) * sizeof(ColTri));
        if (!ct) { lvl_free(buf); return 0; }
        memcpy(ct, buf + pos, (size_t)nCol * sizeof(ColTri));
        pos += (size_t)nCol * sizeof(ColTri);
        maplog("load: collision build%s%s", "", ""); if (!cw_build(&world, ct, (int)nCol)) { lvl_free(buf); return 0; }
    }
    { char t_[64]; snprintf(t_, sizeof t_, "%u textures", (unsigned)nTex); maplog("load: uploading %s%s", t_, ""); }

    texs = calloc(nTex ? nTex : 1, sizeof(GLuint));
    texPan = calloc(nTex ? nTex : 1, 1);
    texAff = calloc(nTex ? nTex : 1, sizeof(float));
    texHasA = calloc(nTex ? nTex : 1, 1); texNm = calloc(nTex ? nTex : 1, 56);
    glGenTextures(nTex, texs); texClampNow = calloc(nTex ? nTex : 1, 1);
    for (uint32_t i = 0; i < nTex; i++) {
        if ((i & 31) == 31) { char t_[48]; snprintf(t_, sizeof t_, "texture %u", (unsigned)i); maplog("load: %s%s", t_, ""); }
        uint8_t nameLen = rd8();
        {   // scrolling textures are recognised by name
            char nm[64]; size_t n = nameLen < 63 ? nameLen : 63;
            for (size_t k = 0; k < n; k++) { char c = (char)buf[pos + k]; nm[k] = (c >= 'A' && c <= 'Z') ? (char)(c + 32) : c; }
            nm[n] = 0; if (texNm) { strncpy(texNm[i], nm, 55); texNm[i][55] = 0; }
            texPan[i] = strstr(nm, "watertransp") != NULL ? 1 : (strstr(nm, "t_rain") != NULL ? 2 : 0);      // 2 = rain: falls fast
            texAff[i] = strstr(nm, "ladder_metal") != NULL ? LADDER_AFFINE : 0.0f;
        }
        pos += nameLen;
        uint16_t w = rd16(), h = rd16();
        glBindTexture(GL_TEXTURE_2D, texs[i]);
        tex_upload(texs[i], w, h, buf + pos);
        for (size_t k = 3; k < (size_t)w * h * 4; k += 4) if (buf[pos + k] < 250) { texHasA[i] = 1; break; }
        pos += (size_t)w * h * 4;
    }

    geoms = calloc(nGeom ? nGeom : 1, sizeof(Geom));
    for (uint32_t i = 0; i < nGeom; i++) {
        uint32_t nv = rd32(), ni = rd32();
        glGenBuffers(1, &geoms[i].vbo);
        glBindBuffer(GL_ARRAY_BUFFER, geoms[i].vbo);
        glBufferData(GL_ARRAY_BUFFER, nv * 20, buf + pos, GL_STATIC_DRAW);
        for (int k = 0; k < 3; k++) { geoms[i].mn[k] = 1e30f; geoms[i].mx[k] = -1e30f; }
        for (uint32_t v = 0; v < nv; v++) {
            float p3[3]; memcpy(p3, buf + pos + (size_t)v * 20, 12);
            for (int k = 0; k < 3; k++) { if (p3[k] < geoms[i].mn[k]) geoms[i].mn[k] = p3[k]; if (p3[k] > geoms[i].mx[k]) geoms[i].mx[k] = p3[k]; }
        }
        geoms[i].nv = nv; geoms[i].cv = malloc((size_t)nv * 20 + 4); if (geoms[i].cv) memcpy(geoms[i].cv, buf + pos, (size_t)nv * 20);
        pos += (size_t)nv * 20;
        glGenBuffers(1, &geoms[i].ibo);
        glBindBuffer(GL_ELEMENT_ARRAY_BUFFER, geoms[i].ibo);
        glBufferData(GL_ELEMENT_ARRAY_BUFFER, ni * 2, buf + pos, GL_STATIC_DRAW);
        geoms[i].ci = malloc((size_t)ni * 2 + 4); if (geoms[i].ci) memcpy(geoms[i].ci, buf + pos, (size_t)ni * 2);
        pos += (size_t)ni * 2;
        geoms[i].nidx = ni;
    }

    draws = calloc(nDraw ? nDraw : 1, sizeof(Drawable));
    for (uint32_t i = 0; i < nDraw; i++) {
        draws[i].nparts = rd16();
        draws[i].parts = calloc(draws[i].nparts ? draws[i].nparts : 1, sizeof(Part));
        for (uint16_t p = 0; p < draws[i].nparts; p++) {
            draws[i].parts[p].geom = rd32();
            draws[i].parts[p].tex = rd16();
        }
        {   // bounding sphere of the whole drawable
            float mn[3] = { 1e30f, 1e30f, 1e30f }, mx[3] = { -1e30f, -1e30f, -1e30f };
            for (uint16_t p = 0; p < draws[i].nparts; p++) {
                const Geom *g = &geoms[draws[i].parts[p].geom];
                for (int k = 0; k < 3; k++) { if (g->mn[k] < mn[k]) mn[k] = g->mn[k]; if (g->mx[k] > mx[k]) mx[k] = g->mx[k]; }
            }
            if (mn[0] > mx[0]) { mn[0] = mn[1] = mn[2] = mx[0] = mx[1] = mx[2] = 0.0f; }
            for (int k = 0; k < 3; k++) draws[i].bc[k] = 0.5f * (mn[k] + mx[k]);
            float dx = mx[0] - mn[0], dy = mx[1] - mn[1], dz = mx[2] - mn[2];
            draws[i].br = 0.5f * sqrtf(dx*dx + dy*dy + dz*dz);
        }
    }

    insts = calloc(nInst ? nInst : 1, sizeof(Instance));
    for (uint32_t i = 0; i < nInst; i++) {
        insts[i].draw = rd32();
        float r[12];
        for (int k = 0; k < 12; k++) r[k] = rdf();
        float *m = insts[i].m;                 // 3x4 row-major -> 4x4 column-major
        m[0] = r[0]; m[1] = r[4]; m[2]  = r[8];  m[3]  = 0;
        m[4] = r[1]; m[5] = r[5]; m[6]  = r[9];  m[7]  = 0;
        m[8] = r[2]; m[9] = r[6]; m[10] = r[10]; m[11] = 0;
        m[12] = r[3]; m[13] = r[7]; m[14] = r[11]; m[15] = 1;
    }
    lvl_free(buf);
    return 1;
}


