#define IX_RANGE      2.2f    /* how close (m) to a door to open it */
#define LAD_RANGE     1.5f
#define LAD_OFF       0.12f   /* how far in front of the ladder's centre the Hunter hangs (m) */
#define LAD_SPEED     1.0f    /* climb speed (m/s) = the climb animation's own rise per second; X doubles both */
#define LAD_REACH     1.62f   /* how far the ReachTop / ClimbDownStart animations lift / drop the Hunter (m) */
#define DOOR_OPEN_ANG 1.75f   /* radians the leaves swing */
typedef struct { uint32_t inst; float hx, hy, ux, uy; uint32_t cs, cc; float base[16]; float sgn; float *bk; } DoorLeaf;      // bk: the leaf's collision triangles, saved before an opened door removes them
typedef struct { float cx, cy, zc, fx, fy; int dbl, nl, open; DoorLeaf lf[4]; int st, which, autoexit, fidx; float afx, afy; char key[24], keyname[28]; } Door;      // st: the game's own lock state (0 open, 1 unlocked, 2 locked (key), 3 locked from inside, 4 locked from outside, 5 locked by device, 255 = unknown); afx/afy: the door Blueprint's forward direction
typedef struct { float cx, cy, z0, z1, px, py; } Ladder;
#define MAX_DOORS 96
#define MAX_LADS  64
static Door doors_[MAX_DOORS]; static int nDoors;
static int g_wch[32], g_nwch; static float g_wch_orig[32][16]; static uint8_t g_wch_have[32];      // chair instances and their matrices as the map placed them (wch_orig)      // instances that are wheelchairs (the one beside a wheelchair enemy rides with him)
static Ladder lads[MAX_LADS]; static int nLads;
static float lad_dz[MAX_LADS], lad_z0o[MAX_LADS], lad_z1o[MAX_LADS], lad_up[MAX_LADS]; static int *lad_mv[MAX_LADS]; static int lad_nmv[MAX_LADS]; static float *lad_bz[MAX_LADS];      // lever_slide: drop distance, original lowest rung, raised amount 1..0, moving segment instances + their raised z
typedef struct { float cx, cy, cz, hx, hy, hz, c, s, a, b; char k, w; char txt[40]; } Vol;      // map_volumes: volumes_<map>.txt = the map's invisible actors (F fall-to-death, T level title, A enemies-lose-hunter, D damage), from extract_volumes.py
static Vol g_vol[48]; static int g_nvol, g_nvolA, g_nvolD, g_nvolF, g_nvolT, g_vol_off;
static int vol_in(char k, float x, float y, float z) {      // -> index + 1 of the first volume of that kind containing the point, 0 if none (boxes can be turned by the actor's yaw)
    for (int i = 0; i < g_nvol; i++) { const Vol *v = &g_vol[i]; if (v->k != k) continue;
        float ux = x - v->cx, uy = -(y - v->cy), lx = ux * v->c + uy * v->s, ly = -ux * v->s + uy * v->c;
        float m_ = v->k == 'T' ? 0.4f : 0.0f; if (fabsf(lx) < v->hx + m_ && fabsf(ly) < v->hy + m_ && fabsf(z - v->cz) < v->hz) return i + 1; }
    return 0;
}
