#define WLG_FACE   g_wlg_face
static void frenzy_add(float amt) { if (g_sed_t > 0.0f) amt *= 0.2f; g_fren += amt; g_fren_idle = 0.0f; }
static float g_pois_build, g_pois_t, g_pcfg[6] = { 100.0f, 1.0f, 6.0f, 25.0f, 4.0f, 0.0f };      // build-up meter, poisoned seconds left; cfg: meter max, build scale, decay per s outside, poisoned seconds, hp lost per s, feet margin above the water top (poison_cfg.txt)
#define MAX_PTC 64
typedef struct { float cx, cy, h, zmin, ux, uy, nx, ny, thick, f, sgn, thmax; int np, lev, tgt, dirty, fix; uint32_t inst[4], cs[4], cc[4]; float m0[4][16]; float *t0; } Ptc;      // ptc_lift: a drawbridge (SM_Portcullis*): stands upright, a lever swings it down about its bottom edge; f = 0 raised .. 1 flat
static Ptc ptcs[MAX_PTC]; static int nPtc;
static uint8_t lad_lock[MAX_LADS], lad_gate[MAX_LADS];      // lever_ladder: ladders the game places raised (IsClimbable = false) until their lever is pulled: gate = it has a lever, lock = still raised
static char g_lad_done[24][40]; static int g_lad_ndone;

// ---- save-point lanterns: rest (X) to refill and bring the enemies back; dying sends you to the last one you lit
typedef struct { float x, y, z; } Lamp;
#define MAX_LAMPS 4
static void maplog(const char *fmt, const char *a, const char *b);
static int lamp_blank(int w, int h, const uint8_t *p) {      // a sprite that is one flat opaque colour (the white panels) or almost invisible
    size_t n = (size_t)w * h, vis = 0; int lo = 255, hi = 0; if (!n) return 1;
    for (size_t i = 0; i < n; i++) { const uint8_t *px = p + i * 4; if (px[3] > 128) { vis++; int l = (px[0] + px[1] + px[2]) / 3; if (l < lo) lo = l; if (l > hi) hi = l; } }
    if (vis * 100 < n * 3) return 1;
    return vis * 100 >= n * 95 && hi - lo < 40;
}
static void lamp_fallback_tex(uint8_t *px) {      // a small iron lantern with amber glass, 16 x 32
    memset(px, 0, 16 * 32 * 4);
    for (int y = 0; y < 32; y++) for (int x = 0; x < 16; x++) {
        int hw = y < 4 ? 5 : (y < 28 ? 6 : 5); float dx = fabsf(x - 7.5f); if (dx > hw - 0.5f) continue;
        uint8_t *p = px + (y * 16 + x) * 4; int frame = (y < 4 || y >= 28 || dx > hw - 2.0f || y == 8 || y == 20);
        if (frame) { p[0] = 52; p[1] = 48; p[2] = 44; } else { float g = 1.0f - dx / 6.0f; p[0] = (uint8_t)(200 + 55 * g); p[1] = (uint8_t)(120 + 90 * g); p[2] = (uint8_t)(40 + 60 * g); }
        p[3] = 255;
    }
}
static Lamp lamps_[MAX_LAMPS]; static int nLamps; static GLuint lampTex, gleamTex, lampVbo;
static int g_lamp_set = 0; static char g_lamp_map[40]; static float g_lamp_x, g_lamp_y, g_lamp_z;
static char g_lit_map[128][32]; static float g_lit_x[128], g_lit_y[128]; static int g_lit_n, g_lamp_light;      // lamp_light: the lanterns you have lit (saved); g_lamp_light = the open menu is the 'light it?' question
static int g_insight;      // insight: +3 per boss slain, +1 per lantern lit; the higher it is the likelier the blood stone drops (saved)
static int g_sick_open;      // death_dream: dying before any lantern was rested at sends you to the Dream and lights the sickroom's lantern for good (saved)
static int lamp_lit_at(const char *map, float x, float y) {
    if (g_sick_open && !strcasecmp(map, "ic_firstfloorsickroom")) return 1;
    if (!strcasecmp(map, "huntersdream") || !strcasecmp(map, "huntersworkshop") || !strcasecmp(map, "romarena") || !strcasecmp(map, "moonarena") || !strcasecmp(map, "romlake")) return 1;      // the Dream's and the Workshop's own lanterns are always lit
    for (int i = 0; i < g_lit_n; i++) if (!strcasecmp(g_lit_map[i], map) && fabsf(g_lit_x[i] - x) < 0.6f && fabsf(g_lit_y[i] - y) < 0.6f) return 1;
    return 0;
}
static int g_start_vials = 20, g_start_bullets = 20, g_cur_vials = -1, g_cur_bullets = -1, g_gift_taken[2], g_gift, g_drop_bul, g_drop_vial;      // starter_kit: vials / bullets are saved now; gift = the weapon messenger's free choice; drop_* = what enemies dropped, collected by the main loop
static int g_dream_seen;      // lamp_gone: you have been to the Hunter's Dream (saved)
static int lamp_gone(int i) { (void)i; return !g_dream_seen && !strcasecmp(cur_map, "ic_firstfloorsickroom"); }      // the sickroom's lantern does not exist until you have travelled to the Dream from another lantern
static int lamp_lit(int i) { return lamp_lit_at(cur_map, lamps_[i].x, lamps_[i].y); }
static void lamp_light_it(const char *map, float x, float y) { if (lamp_lit_at(map, x, y) || g_lit_n >= 128) return; snprintf(g_lit_map[g_lit_n], 32, "%s", map); g_lit_x[g_lit_n] = x; g_lit_y[g_lit_n] = y; g_lit_n++; }
static GLuint lampPostTex, beamTex; static char lamp_ovr_map[40];
static int g_gas_dead = 0;          /* Father Gascoigne has been killed (saved): his arena lantern exists from then on */
static int lamp_hidden = 0;         /* lanterns this map has but that are held back (the arena's, until the boss is dead) */
static float g_boss_hpf = -1.0f;    /* boss health bar (0..1), < 0 = none */
static int g_hud_menu;      // hud_hide: a menu is open (the boss bar is hidden, the pop-up messages stay)
static const char *g_boss_name = ""; static const char *g_en_name = "";      // g_en_name: a small name over the corner enemy bar (Eileen)
static int g_banner_shown = 0;      // night_sys: the 'PREY SLAUGHTERED' banner has appeared (the night cutscene waits for it to finish)
static int g_banner_which = 0;      // 0 PREY SLAUGHTERED, 2 NIGHTMARE SLAIN
