typedef struct { int count, cat; char key[24], label[28]; } PItem;     // cat: 0 blood vial, 1 quicksilver bullets, 2 consumable, 3 key, 4 attire, 5 material, 6 other, 7 weapon unlocked
typedef struct { float x, y, z; int kind, count, taken; int ni, norefresh; PItem it[2]; int dyn; } Pickup;      // kind 0 = blood vials, 1 = quicksilver bullets (old files); ni > 0: what the game's own Blueprint says it gives
#define MAX_PICKS 32
// what you are carrying besides vials and bullets (keys, shards, molotovs ...): saved in save.bin
typedef struct { char key[24]; char label[28]; int cat, n; } InvSlot;
#define MAX_INV 40
static InvSlot g_inv[MAX_INV];
static int inv_have(const char *key) { for (int i = 0; i < MAX_INV; i++) if (g_inv[i].n > 0 && !strcasecmp(g_inv[i].key, key)) return g_inv[i].n; return 0; }
static int inv_cat_fix(const char *k, int c);
static void inv_add(const char *key, const char *label, int cat, int n) {
    cat = inv_cat_fix(key, cat); int f = -1; if (!strcasecmp(key, "LightningPaper")) label = "BOLT PAPER";      // renamed: lightning paper is bolt paper
    for (int i = 0; i < MAX_INV; i++) { if (g_inv[i].n > 0 && !strcasecmp(g_inv[i].key, key)) { f = i; break; } if (g_inv[i].n <= 0 && f == -1) f = -2 - i; }      // inv_reuse: any used-up slot is free again (before, a slot whose item ran out stayed taken, so a long game filled all 40 and new items such as keys were silently lost)
    if (f <= -2) { int i = -2 - f; memset(&g_inv[i], 0, sizeof g_inv[i]); snprintf(g_inv[i].key, sizeof g_inv[i].key, "%s", key); snprintf(g_inv[i].label, sizeof g_inv[i].label, "%s", label); g_inv[i].cat = cat; f = i; }
    if (f < 0) { maplog("inventory FULL: could not add %s%s", key, ""); return; }
    g_inv[f].n += n; if (g_inv[f].n > (cat == 3 ? 1 : 99)) g_inv[f].n = cat == 3 ? 1 : 99;
}
static InvSlot g_istore[MAX_INV];      // item_store: ordinary items kept in the Hunter's Workshop storage (saved; they free their bag slots)
static int inv_room(const char *key) { for (int i = 0; i < MAX_INV; i++) { if (g_inv[i].n > 0 && !strcasecmp(g_inv[i].key, key)) return 1; if (g_inv[i].n <= 0) return 1; } return 0; }      // bag_full: can this item still be added?
static int ci_has(const char *hay, const char *sub);
static int coldblood_echoes(const char *k) { return ci_has(k, "thick") ? (ci_has(k, "6") ? 10000 : 5000) : (ci_has(k, "3") ? 2000 : (ci_has(k, "2") ? 1000 : 500)); }      // echo consumables: Dew 1 / 2 / 3 = 500 / 1000 / 2000, Thick Coldblood 5 / 6 = 5000 / 10000 (guessed amounts)
static int inv_cat_fix(const char *k, int c) { return (ci_has(k, "huntersmark") || ci_has(k, "coldblood") || ci_has(k, "dew") || ci_has(k, "blacksky") || (ci_has(k, "throw") && ci_has(k, "knife"))) ? 2 : c; }      // coldblood / blacksky: usable items (they can sit in a quick slot), not materials
static int inv_med(const char *w) { int n = 0; for (int i = 0; i < MAX_INV; i++) if (g_inv[i].n > 0 && ci_has(g_inv[i].key, w)) n += g_inv[i].n; return n; }      // shop_meds: how many antidotes / sedatives are carried (any key containing the word)
static void inv_med_add(const char *w) {      // adds one to the stack you already carry (whatever key the map gave it), else starts a new one
    for (int i = 0; i < MAX_INV; i++) if (g_inv[i].n > 0 && ci_has(g_inv[i].key, w)) { if (g_inv[i].n < 99) g_inv[i].n++; return; }
    if (w[0] == 'f') inv_add("FirePaper", "FIRE PAPER", 2, 1); else if (w[0] == 'l') inv_add("LightningPaper", "BOLT PAPER", 2, 1); else if (w[0] == 'p') inv_add("Pebble", "PEBBLE", 2, 1); else if (w[0] == 'm') inv_add("Molotov", "MOLOTOV COCKTAIL", 2, 1); else if (w[0] == 'k') inv_add("ThrowingKnife", "THROWING KNIFE", 2, 1);      // throwables
    else inv_add(w[0] == 'a' ? "Antidote" : "Sedative", w[0] == 'a' ? "ANTIDOTE" : "SEDATIVE", 2, 1);
}
