static void say(const char *s_) {
    static const char *const QUIET[] = { "BOUGHT ", "LEVEL ", "GAINED ", "BLOOD BULLETS +", "RECEIVED " };      // quiet_msgs: confirmations the HUD already shows (shops, level up, echoes); warnings, locks and key items still pop up
    for (unsigned i = 0; i < sizeof QUIET / sizeof *QUIET; i++) if (!strncmp(s_, QUIET[i], strlen(QUIET[i]))) return;
    snprintf(g_msg, sizeof g_msg, "%s", s_); g_msg_t = 2.6f; }

