typedef struct { char key[24]; char label[28]; int cat, n, kind; } InvRow;           // kind 0 = an entry of g_inv, 1 = blood vials, 2 = quicksilver bullets (their counts live in the game loop), 3 = "empty the slot"
static void quick_ready(void) { if (g_quick_ready) return; g_quick_ready = 1; memset(g_quick, 0, sizeof g_quick); g_quick_sel = 0; }
static int quick_row(const char *key, int vials, int bullets, InvRow *r) {      // fills r for the item a quick slot holds; 0 when the slot is empty
    if (!key[0]) return 0;
    memset(r, 0, sizeof *r); snprintf(r->key, sizeof r->key, "%s", key);
    if (!strcasecmp(key, "bloodvial") || !strcasecmp(key, "quicksilverbullet")) return 0;      // permanently equipped (own boxes), never a quick-slot item (older saves may still list them)
    for (int i = 0; i < MAX_INV; i++) if (g_inv[i].n > 0 && !strcasecmp(g_inv[i].key, key)) { snprintf(r->label, sizeof r->label, "%s", !strcasecmp(g_inv[i].key, "LightningPaper") ? "BOLT PAPER" : (g_inv[i].label[0] ? g_inv[i].label : g_inv[i].key)); r->cat = g_inv[i].cat; r->n = g_inv[i].n; return 1; }
    return 0;                                                                   // something we no longer carry
}
static int ci_has(const char *hay, const char *sub);
static int trans_name(const char *t) { if (!t || !t[0]) return 0; static char cfg_[40]; static int ld_ = 0; if (!ld_) { ld_ = 1; FILE *f = fopen("ux0:data/bbpsx/bt_item.txt", "r"); if (f) { if (fscanf(f, "%39s", cfg_) != 1) cfg_[0] = 0; fclose(f); } }      // bt_item.txt: the item's exact key, if the guesses below miss
    return (cfg_[0] && ci_has(t, cfg_)) || ci_has(t, "transf") || ci_has(t, "bullettrans") || ci_has(t, "bullet_trans") || ci_has(t, "bullet trans") || (ci_has(t, "bullet") && ci_has(t, "trans") && !ci_has(t, "quicksilver")); }
static int inv_has_trans(void) { for (int i = 0; i < MAX_INV; i++) if (g_inv[i].n > 0 && (trans_name(g_inv[i].key) || trans_name(g_inv[i].label))) return 1; return 0; }      // bullet_trans: the Bullet Transfuser (found in the sickroom) is carried
static int quick_is_vial(void) { quick_ready(); return !strcasecmp(g_quick[g_quick_sel], "bloodvial"); }
static int g_quick_mono(void) { quick_ready(); const char *k = g_quick[g_quick_sel]; if (!k[0]) return 0; for (int i = 0; i < MAX_INV; i++) if (g_inv[i].n > 0 && !strcasecmp(g_inv[i].key, k)) return ci_has(k, "monocul") || ci_has(g_inv[i].label, "monocul"); return 0; }      // the selected quick item is the Monocular (and still carried)
static void quick_cycle(void) { quick_ready(); for (int k = 1; k <= 6; k++) { int i = (g_quick_sel + k) % 6; if (g_quick[i][0] && strcasecmp(g_quick[i], "bloodvial") && strcasecmp(g_quick[i], "quicksilverbullet")) { g_quick_sel = i; return; } } }
