    float p1x = uy*rz - uz*ry, p1y = uz*rx - ux*rz, p1z = ux*ry - uy*rx; float pl = sqrtf(p1x*p1x + p1y*p1y + p1z*p1z); if (pl < 1e-4f) return; p1x /= pl; p1y /= pl; p1z /= pl;
    float p2x = uy*p1z - uz*p1y, p2y = uz*p1x - ux*p1z, p2z = ux*p1y - uy*p1x;
