    float sc[3]; hat_match_scale(sm, sc); { char t_[160]; snprintf(t_, sizeof t_, "hat_match: own garb colour %.0f %.0f %.0f -> scale %.2f %.2f %.2f", sm[0], sm[1], sm[2], sc[0], sc[1], sc[2]); maplog("%s%s", t_, ""); }
    if (sc[0] > 0.999f && sc[1] > 0.999f && sc[2] > 0.999f) return;
