typedef struct { int active, amt; char map[40]; float x, y, z; } EchoDrop;
static EchoDrop g_drop;
static int echo_value(int type) { switch (type) { case 19: return 5000; case 1: return ECHO_RAT; case 2: return ECHO_CROW; case 4: return ECHO_GAS; case 5: return 150; case 6: return 40; case 7: return 250; case 8: case 9: return 65; case 10: return 95; case 11: return 70; case 12: case 13: case 14: return 60; case 15: return 220; case 16: return 200; case 17: return 90; default: return ECHO_YHARN; } }      // 5 werewolf, 6 rabid dog, 7 troll, 8-11 the other Yharnamites
static void echo_matrix(float *m, float t) {            // the dropped echoes: a bigger, slower red gem
    Pickup p; memset(&p, 0, sizeof p); p.x = g_drop.x; p.y = g_drop.y; p.z = g_drop.z + 0.25f;
    gem_matrix(m, &p, t * 0.7f);
    m[0] *= 1.9f; m[1] *= 1.9f; m[4] *= 1.9f; m[5] *= 1.9f; m[10] *= 1.9f;
}
