static GLuint faTex;
static const char *fa_tok(const char *str, const char *q, int *len) {      // a {TOKEN} or a lone word (X O SQUARE TRIANGLE L1 R1 L2 R2 START SELECT) in menu text: the game's button art for it, or NULL
    static const struct { const char *tok, *ui; int imp; } M[] = { { "L1", "T_ButtonL1", 1 }, { "R1", "T_ButtonR1", 1 }, { "L2", "T_ButtonL2", 1 }, { "R2", "T_ButtonR2", 1 }, { "START", "T_ButtonStart", 1 }, { "SELECT", "T_ButtonSelect", 1 },
        { "X", "T_FaceButtonCross", 1 }, { "O", "T_FaceButtonCircle", 1 }, { "SQUARE", "T_FaceButtonBox", 1 }, { "TRIANGLE", "T_FaceButtonTriangle", 1 },
        { "D-PAD UP", "T_D-padUp", 0 }, { "D-PAD DOWN", "T_D-padDown", 0 }, { "D-PAD LEFT", "T_D-padLeft", 0 }, { "D-PAD RIGHT", "T_D-padRight", 0 } };
    if (*q == '{') {
        const char *e = strchr(q, '}'); if (!e || e - q > 12) return NULL; int n = (int)(e - q - 1);
        for (unsigned i = 0; i < sizeof M / sizeof M[0]; i++) if ((int)strlen(M[i].tok) == n && !strncmp(M[i].tok, q + 1, n) && ui_get(M[i].ui)) { *len = n + 2; return M[i].ui; }
        return NULL;
    }
    if (!isalnum((unsigned char)*q) || (q > str && (isalnum((unsigned char)q[-1]) || q[-1] == '%' || q[-1] == '-' || q[-1] == '{'))) return NULL;
    for (unsigned i = 0; i < sizeof M / sizeof M[0]; i++) if (M[i].imp) { int n = (int)strlen(M[i].tok); if (!strncmp(M[i].tok, q, n) && !isalnum((unsigned char)q[n]) && q[n] != '%' && q[n] != '.' && q[n] != '-' && q[n] != ':' && q[n] != '{' && ui_get(M[i].ui)) { *len = n; return M[i].ui; } }
    return NULL;
}
// serif font atlas (digits and capitals, pre-rendered): draws `str` with its cap height = capH HUD units; x = left edge, y = top of the capitals. Returns the width drawn.
static float fa_run(const char *str, float x, float y, float capH, float r, float g, float b, float a, int draw) {
    float sc = capH / 38.0f, w = 0.0f;
    const int W = FA_CW * FA_COLS, Hh = FA_CH * 3;
    if (draw && !faTex) {
        unsigned char *px = malloc((size_t)W * Hh * 4);
        for (int i = 0; i < W * Hh; i++) { px[i * 4] = px[i * 4 + 1] = px[i * 4 + 2] = 255; px[i * 4 + 3] = FA_PIX[i]; }
        glGenTextures(1, &faTex); glBindTexture(GL_TEXTURE_2D, faTex);
        glTexImage2D(GL_TEXTURE_2D, 0, GL_RGBA, W, Hh, 0, GL_RGBA, GL_UNSIGNED_BYTE, px); free(px);
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_LINEAR); glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_LINEAR);
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_CLAMP_TO_EDGE); glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_CLAMP_TO_EDGE);
    }
    if (draw) { glEnable(GL_TEXTURE_2D); glEnableClientState(GL_TEXTURE_COORD_ARRAY); glBindTexture(GL_TEXTURE_2D, faTex); }
    for (const char *q = str; *q; q++) {
        { int tl = 0; const char *ic = fa_tok(str, q, &tl);
          if (ic) { float isz = capH * 1.3f, tn = (r + g + b) > 0.01f ? 1.0f : 0.0f; if (draw) { ui_quad(ic, x + w, y - capH * 0.25f, isz, isz, 1.0f, tn, tn, tn, a); glBindTexture(GL_TEXTURE_2D, faTex); } w += isz + capH * 0.25f; q += tl - 1; continue; } }
        int ch = toupper((unsigned char)*q), idx = ch >= '0' && ch <= '9' ? ch - '0' : (ch >= 'A' && ch <= 'Z' ? 10 + ch - 'A' : -1);
        if (idx < 0) { w += 14.0f * sc; continue; }
        float adv = FA_ADV[idx] * sc;
        if (draw) {
            float cx = (x + w + adv * 0.5f - FA_CW * 0.5f * sc) * hud_k, cy = (y - 6.0f * sc) * hud_k, cw_ = FA_CW * sc * hud_k, chh = FA_CH * sc * hud_k;
            float u0 = (float)((idx % FA_COLS) * FA_CW) / W, u1 = u0 + (float)FA_CW / W, v0 = (float)((idx / FA_COLS) * FA_CH) / Hh, v1 = v0 + (float)FA_CH / Hh;
            float v[8] = { cx, cy, cx + cw_, cy, cx, cy + chh, cx + cw_, cy + chh }, uv[8] = { u0, v0, u1, v0, u0, v1, u1, v1 };
            glColor4f(r, g, b, a); glVertexPointer(2, GL_FLOAT, 0, v); glTexCoordPointer(2, GL_FLOAT, 0, uv); glDrawArrays(GL_TRIANGLE_STRIP, 0, 4);
        }
        w += adv;
    }
    return w;
}
// dlg_font: dlgfont.bin = the game's own Times Bold, all of ASCII (lowercase and punctuation too); {L1} {X} {O} {SQUARE} {TRIANGLE} {START} {R2} {D-PAD UP} ... draw the game's real button art inline
static GLuint fbTex; static int fb_ok = -1, fb_cw, fb_ch, fb_cols, fb_base, fb_cap; static unsigned char fb_adv[95];
static void fb_load(void) {
    fb_ok = 0; FILE *f = fopen("ux0:data/bbpsx/dlgfont.bin", "rb"); if (!f) f = fopen("app0:dlgfont.bin", "rb"); if (!f) return;
    char mg[4]; uint16_t h[5];
    if (fread(mg, 1, 4, f) != 4 || memcmp(mg, "DFN1", 4) || fread(h, 2, 5, f) != 5 || fread(fb_adv, 1, 95, f) != 95) { fclose(f); return; }
    fb_cw = h[0]; fb_ch = h[1]; fb_cols = h[2]; fb_base = h[3]; fb_cap = h[4]; int rows = (95 + fb_cols - 1) / fb_cols;
    size_t n = (size_t)fb_cw * fb_cols * fb_ch * rows; unsigned char *a8 = malloc(n), *px = malloc(n * 4);
    if (a8 && px && fread(a8, 1, n, f) == n) {
        for (size_t i = 0; i < n; i++) { px[i * 4] = px[i * 4 + 1] = px[i * 4 + 2] = 255; px[i * 4 + 3] = a8[i]; }
        glGenTextures(1, &fbTex); glBindTexture(GL_TEXTURE_2D, fbTex);
        glTexImage2D(GL_TEXTURE_2D, 0, GL_RGBA, fb_cw * fb_cols, fb_ch * rows, 0, GL_RGBA, GL_UNSIGNED_BYTE, px);
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_LINEAR); glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_LINEAR);
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_CLAMP_TO_EDGE); glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_CLAMP_TO_EDGE); fb_ok = 1;
    }
    free(a8); free(px); fclose(f);
}
static const char *fb_icon(const char *t, int n) {      // the game's own button art for a {TOKEN}
    static const struct { const char *tok, *ui; } M[] = { {"L1", "T_ButtonL1"}, {"R1", "T_ButtonR1"}, {"L2", "T_ButtonL2"}, {"R2", "T_ButtonR2"}, {"START", "T_ButtonStart"}, {"SELECT", "T_ButtonSelect"},
        {"X", "T_FaceButtonCross"}, {"O", "T_FaceButtonCircle"}, {"SQUARE", "T_FaceButtonBox"}, {"TRIANGLE", "T_FaceButtonTriangle"},
        {"D-PAD UP", "T_D-padUp"}, {"D-PAD DOWN", "T_D-padDown"}, {"D-PAD LEFT", "T_D-padLeft"}, {"D-PAD RIGHT", "T_D-padRight"} };
    for (unsigned i = 0; i < sizeof M / sizeof M[0]; i++) if ((int)strlen(M[i].tok) == n && !strncmp(M[i].tok, t, n) && ui_get(M[i].ui)) return M[i].ui;
    return NULL;
}
static float fb_run(const char *str, float x, float y, float capH, float r, float g, float b, float a, int draw) {
    if (fb_ok < 0) fb_load();
    if (fb_ok == 0) return fa_run(str, x, y, capH, r, g, b, a, draw);      // no dlgfont.bin: the old capitals-only font
    float sc = capH / (float)fb_cap, w = 0.0f; int rows = (95 + fb_cols - 1) / fb_cols; const float TW = (float)(fb_cw * fb_cols), TH = (float)(fb_ch * rows);
    for (const char *q = str; *q; q++) {
        if (*q == '{') { const char *e = strchr(q, '}'); if (e && e - q < 14) { const char *ic = fb_icon(q + 1, (int)(e - q - 1)); if (ic) { float sz = capH * 1.25f; if (draw) ui_quad(ic, x + w, y - capH * 0.2f, sz, sz, 1.0f, 1.0f, 1.0f, 1.0f, a); w += sz + capH * 0.2f; q = e; continue; } } continue; }
        if (*q == '}') continue;
        int idx = (unsigned char)*q - 32; if (idx < 0 || idx > 94) { w += 14.0f * sc; continue; }
        float adv = fb_adv[idx] * sc;
        if (draw && idx > 0) {
            glEnable(GL_TEXTURE_2D); glEnableClientState(GL_TEXTURE_COORD_ARRAY); glBindTexture(GL_TEXTURE_2D, fbTex);
            float cx = (x + w - 4.0f * sc) * hud_k, cy = (y - (fb_base - fb_cap) * sc) * hud_k, cw_ = fb_cw * sc * hud_k, chh = fb_ch * sc * hud_k;
            float u0 = (float)((idx % fb_cols) * fb_cw) / TW, u1 = u0 + (float)fb_cw / TW, v0 = (float)((idx / fb_cols) * fb_ch) / TH, v1 = v0 + (float)fb_ch / TH;
            float v[8] = { cx, cy, cx + cw_, cy, cx, cy + chh, cx + cw_, cy + chh }, uv[8] = { u0, v0, u1, v0, u0, v1, u1, v1 };
            glColor4f(r, g, b, a); glVertexPointer(2, GL_FLOAT, 0, v); glTexCoordPointer(2, GL_FLOAT, 0, uv); glDrawArrays(GL_TRIANGLE_STRIP, 0, 4);
        }
        w += adv;
    }
    return w;
}
// Right-aligned number at x (HUD units); `s` sizes it (cap height = 5 s)
static void hud_number(int val, float xr, float y, float s, float r, float g, float b) {
    char buf[12]; snprintf(buf, sizeof buf, "%d", val < 0 ? 0 : val);
    float w = fa_run(buf, 0, 0, 5.0f * s, 0, 0, 0, 0, 0), x = xr - w;
    fa_run(buf, x + s * 0.5f, y + s * 0.5f, 5.0f * s, 0, 0, 0, 0.85f, 1);        // shadow
    fa_run(buf, x, y, 5.0f * s, r, g, b, 1.0f, 1);
}

