            if (r->kind != 3 && r->kind != 4) { char hb[24]; snprintf(hb, sizeof hb, "Held %d", r->n); fb_run(hb, dx + 24, ty + 74, 18.0f, 0.78f, 0.74f, 0.66f, 1.0f, 1); }
            glDisable(GL_TEXTURE_2D); hud_rect((dx + 24) * hud_k, (ty + 108) * hud_k, (dw - 48) * hud_k, 1.5f * hud_k, 0.6f, 0.52f, 0.36f, 0.8f);
