        float stp_ = fminf(50.0f, (Hh - 80.0f - (py + 70.0f)) / (float)SYS_N);      // sys_fit: every row has to fit above the footer
        float y = py + 70.0f + i * stp_; int sel = i == g_sys_sel; char t_[96]; mn_tc(g_sys_txt[SYS_MAP[i]], t_, sizeof t_);
        float tw_ = fb_run(t_, 0, 0, 17.0f, 0, 0, 0, 0, 0), cx_ = W * 0.5f - tw_ * 0.5f;
        if (sel) mn_bar((W * 0.5f - (tw_ + 70.0f) * 0.5f) * hud_k, (y - 6.0f) * hud_k, (tw_ + 70.0f) * hud_k, 29.0f * hud_k);
        glEnable(GL_TEXTURE_2D); fb_run(t_, cx_ + 1.0f, y + 1.0f, 17.0f, 0, 0, 0, 0.7f, 1);
