static int g_hud_q = -1;
static const char *UP_MAT[4] = { "BLOOD STONE SHARD", "TWIN BLOOD STONE SHARDS", "BLOOD STONE CHUNK", "BLOOD ROCK" };
static int up_mat_idx(int tier) {      // wpn_upgrade: the bag slot holding that tier of blood stone (matched by name), -1 if none
    for (int i = 0; i < MAX_INV; i++) { if (g_inv[i].n <= 0) continue; const char *k = g_inv[i].key, *l = g_inv[i].label;
        int tw = ci_has(k, "twin") || ci_has(l, "twin");
        if (tier == 0 && (ci_has(k, "shard") || ci_has(l, "shard")) && !tw) return i;
        if (tier == 1 && tw) return i;
        if (tier == 2 && (ci_has(k, "chunk") || ci_has(l, "chunk"))) return i;
        if (tier == 3 && (ci_has(k, "rock") || ci_has(l, "rock"))) return i; }
    return -1; }
static void up_need(int lv, int *tier, int *cnt) { int n = lv + 1; *tier = (n - 1) / 3; if (*tier > 3) *tier = 3; *cnt = *tier >= 3 ? 1 : ((n - 1) % 3) + 1; if (*tier >= 3) { *tier = 2; *cnt = 4; } }      // no_rock: +10 takes 4 chunks instead of a blood rock      // the next level (lv -> lv + 1): +1..+3 shards x1..3, +4..+6 twin shards, +7..+9 chunks, +10 a rock
