            int cost_ = id_ >= 0 && id_ < 10 ? SHOP_COST[id_] : (id_ == 1 ? SHOP_COST[1] : (id_ >= 300 ? ATT_PRICE[1][id_ - 300] : (id_ >= 200 ? ATT_PRICE[0][id_ - 200] : (id_ >= 100 ? WPN_PRICE[id_ - 100] : 0))));
