static int stain_off(void) {      // noblood_switch: a file ux0:data/bbpsx/noblood.txt turns the blood patches on the Hunter off (to tell whether they are what changes his colour)
    static int v = -1; if (v < 0) { { FILE *nf_ = fopen("ux0:data/bbpsx/noblood.txt", "rb"); v = nf_ ? 1 : 0; if (nf_) fclose(nf_); } maplog("blood patches: %s%s", v ? "OFF (noblood.txt)" : "on", ""); }
    return v;
}
static void stain_add(int n, float zlo, float zhi) {      // pick triangles of the body (not the hats or weapons) between those heights, side-on to the middle of the body
    if (stain_off()) return;
    if (!HUNT.ok || !HUNT.skinned || !HUNT.nS) return;
    float ztop_ = 0.0f; for (uint32_t si = 0; si < HUNT.nS; si++) { if (HUNT.sec[si].flag != 0) continue; const uint16_t *ix_ = HUNT.idx + HUNT.sec[si].start; for (uint32_t q_ = 0; q_ < HUNT.sec[si].count; q_++) { float z_ = HUNT.skinned[ix_[q_] * 5 + 2]; if (z_ > ztop_) ztop_ = z_; } }      // head_pose: the top of his head in this very pose (a hurt or bent-over animation lowers it, which let blood onto the face)
    float zhead_ = ztop_ - 0.42f; if (zhead_ > 1.45f || ztop_ < 0.5f) zhead_ = 1.45f;
    int ok_ = 0; if (zhi > zhead_) zhi = zhead_;      // the body: up to the shoulders; the head gets at most 8% of the spots (below)
    for (int k = 0; k < n; k++) {
        float cr_ = frand(); int cls_ = cr_ < 0.5f ? 0 : (cr_ < 0.8f ? 2 : 1), head_ = 0;      // no_head_blood: the hat and face stay clean
         float zt_ = head_ ? 1.5f + frand() * 0.3f : zlo + frand() * (zhi - zlo);      // 50% front, 30% back, 20% sides; the height is picked first so the dense head / hand triangles don't hog it
        for (int tries = 0; tries < 400; tries++) {
            uint32_t si = (uint32_t)(frand() * HUNT.nS); if (si >= HUNT.nS) si = HUNT.nS - 1;
            if (HUNT.sec[si].flag != 0 || HUNT.sec[si].count < 3) continue;
            uint32_t nt = HUNT.sec[si].count / 3, ti = (uint32_t)(frand() * nt); if (ti >= nt) ti = nt - 1;
            const uint16_t *ix = HUNT.idx + HUNT.sec[si].start + ti * 3; const float *P0 = HUNT.skinned + ix[0] * 5, *P1 = HUNT.skinned + ix[1] * 5, *P2 = HUNT.skinned + ix[2] * 5;
            float cz = (P0[2] + P1[2] + P2[2]) / 3.0f; if (fabsf(cz - zt_) > (tries < 250 ? 0.1f : 0.35f)) continue;
            { float cx0_ = (P0[0] + P1[0] + P2[0]) / 3.0f, cy0_ = (P0[1] + P1[1] + P2[1]) / 3.0f; if (cx0_ * cx0_ + cy0_ * cy0_ > 1e-4f) { float ang_ = fabsf(atan2f(cy0_, cx0_)); if (cls_ == 0 ? ang_ > 1.3f : (cls_ == 2 ? ang_ < 2.0f : (ang_ < 1.3f || ang_ > 2.0f))) continue; } }      // model +x is the way he faces
            float ux = P1[0] - P0[0], uy = P1[1] - P0[1], uz = P1[2] - P0[2], vx = P2[0] - P0[0], vy = P2[1] - P0[1], vz = P2[2] - P0[2];
            float nx = uy * vz - uz * vy, ny = uz * vx - ux * vz, nz = ux * vy - uy * vx, nl = sqrtf(nx * nx + ny * ny + nz * nz);
            if (nl < 1e-6f) continue;
            float cx = (P0[0] + P1[0] + P2[0]) / 3.0f, cy = (P0[1] + P1[1] + P2[1]) / 3.0f, cl = sqrtf(cx * cx + cy * cy);
            if ((g_att[1] == 3 || g_att[1] == 7) && cx < -0.16f && cz > 0.3f && cz < 1.05f) continue;      // foreign_tail: the foreign garb has no coat tail, so nothing sticks where the Hunter's own coat hangs behind him
            if (cz > zhead_ || cl > 0.55f || (cl > 0.3f && (cx > 0.25f || cz < 0.8f))) continue;      // arm_blood: the upper arms and sleeves get blood, but not the hands or forearms out in front (where the weapons are) and never the hat
            if (cl > 1e-3f && fabsf((nx * cx + ny * cy) / (nl * cl)) < 0.2f) continue;      // faces up / down / along the body: nothing would show
            Stain *q = &g_stain[g_stain_n++ % STAIN_MAX];
            q->v[0] = ix[0]; q->v[1] = ix[1]; q->v[2] = ix[2];
            q->b0 = frand() * 0.7f; q->b1 = frand() * (1.0f - q->b0); q->size = 0.03f + frand() * 0.04f; q->rot = frand() * 6.2832f; q->age = 0.0f; q->life = 22.0f + frand() * 10.0f;
            ok_++; break;
        }
    }
    (void)ok_;      // log_quiet: this line was written on every hit, in the middle of the fight
}
