      glGenTextures(1, &glowTexR); glBindTexture(GL_TEXTURE_2D, glowTexR); glTexImage2D(GL_TEXTURE_2D, 0, GL_RGBA, GS_, GS_, 0, GL_RGBA, GL_UNSIGNED_BYTE, gx);
