        float ph_ = g->x * 3.1f + g->y * 5.3f, fl = 1.0f + 0.09f * sinf(g_glow_t * 11.0f + ph_) + 0.06f * sinf(g_glow_t * 23.0f + ph_ * 1.7f) + 0.04f * sinf(g_glow_t * 4.3f + ph_ * 0.6f), fadein = g->life > 0.12f ? 1.0f : g->life / 0.12f, sz = g->r * fl * (0.6f + 0.4f * fadein);
