// The flames sit on the walls around the Dream's doors (not the garden gate), 4.5 m tall; with no doors found they fall back to a grid over the house's footprint. ux0:data/bbpsx/house_fire.txt ("x y z_low z_high" per line) replaces the built-in grid.
static float g_ghg[5]; static int g_ghg_ok;      // (declared again further down: the garden gate's position)
static float g_dream_day = 0.0f;      // dream_day: 1 = the Hunter's Dream before the house burns (a brighter, calmer look), 0 = the usual gloom; eased over a few seconds
static int g_hfire; static float g_hf[48][4]; static int g_nhf = -1; static float g_rf[40][3]; static int g_nrf;      // g_rf: points on the roof where embers lift off
static void house_fire_update(float dt) {
    if (g_gh_dead || GH_READY) g_hfire = 1;
    { float tg_ = (!strcasecmp(cur_map, "huntersdream") && !g_hfire) ? 1.0f : 0.0f; g_dream_day += (tg_ - g_dream_day) * fminf(1.0f, 0.8f * dt); if (fabsf(tg_ - g_dream_day) < 0.01f) g_dream_day = tg_; }      // the brightness eases in and out
    static char hm_[32]; if (strcmp(hm_, cur_map)) { snprintf(hm_, sizeof hm_, "%s", cur_map); g_nhf = -1; }
    if (!g_hfire || strcasecmp(cur_map, "huntersdream")) return;
    if (g_nhf < 0) {
        g_nhf = 0; FILE *f = fopen("ux0:data/bbpsx/house_fire.txt", "r");
        if (f) { float a, b, c, d; while (g_nhf < 48 && fscanf(f, "%f %f %f %f", &a, &b, &c, &d) == 4) { g_hf[g_nhf][0] = a; g_hf[g_nhf][1] = b; g_hf[g_nhf][2] = c; g_hf[g_nhf][3] = d; g_nhf++; } fclose(f); }
        if (!g_nhf) for (int i = 0; i < nDoors && g_nhf < 45; i++) {      // the house is the walls around the Dream's doors; the garden gate (the boss fight's door) is left out
            if (hypotf(doors_[i].cx + 25.1f, doors_[i].cy + 14.2f) < 7.0f) continue;
            float fl = doors_[i].zc - 1.0f, l = hypotf(doors_[i].afx, doors_[i].afy); if (l < 0.01f) continue;
            float tx = -doors_[i].afy / l, ty = doors_[i].afx / l; cw_floor(&world, doors_[i].cx, doors_[i].cy, doors_[i].zc + 0.5f, &fl);
            float hw = (doors_[i].dbl ? 1.9f : 1.1f) + 0.9f;      // doorway_clear: the flames burn beside the doorway (its half width plus a margin), never across it, so you can still walk through
            for (int k = -1; k <= 1 && g_nhf < 48; k += 2) { g_hf[g_nhf][0] = doors_[i].cx + tx * hw * k; g_hf[g_nhf][1] = doors_[i].cy + ty * hw * k; g_hf[g_nhf][2] = fl; g_hf[g_nhf][3] = fl + 4.0f; g_nhf++; }
        }
        if (!g_nhf) for (int ix = 0; ix < 5; ix++) for (int iy = 0; iy < 5 && g_nhf < 48; iy++) {
            float x = 14.5f + 3.0f * ix, y = -28.0f + 2.5f * iy, top, low;
            if (!cw_floor(&world, x, y, 60.0f, &top)) continue;
            if (!cw_floor(&world, x, y, 1.5f, &low)) low = top;
            g_hf[g_nhf][0] = x; g_hf[g_nhf][1] = y; g_hf[g_nhf][2] = low; g_hf[g_nhf][3] = top; g_nhf++;
        }
        if (g_nhf > 0) {      // house_fire_skip: no flames within 7 m of the boss fight's garden gate (-25.1 -14.2) (more spots: ux0:data/bbpsx/house_fire_skip.txt, "x y radius" per line)
        float sk[8][3]; int ns = 1; sk[0][0] = g_ghg_ok ? g_ghg[0] : -25.1f; sk[0][1] = g_ghg_ok ? g_ghg[1] : -14.2f; sk[0][2] = 7.0f;
        FILE *f = fopen("ux0:data/bbpsx/house_fire_skip.txt", "r"); if (f) { while (ns < 8 && fscanf(f, "%f %f %f", &sk[ns][0], &sk[ns][1], &sk[ns][2]) == 3) ns++; fclose(f); }
        int w = 0; for (int i = 0; i < g_nhf; i++) { int drop = 0; for (int q = 0; q < ns; q++) if (hypotf(g_hf[i][0] - sk[q][0], g_hf[i][1] - sk[q][1]) < sk[q][2]) drop = 1; if (!drop) { memcpy(g_hf[w], g_hf[i], sizeof g_hf[0]); w++; } }
        g_nhf = w; if (!w) g_nhf = 0;
    }
        g_nrf = 0;
        { char t_[80]; snprintf(t_, sizeof t_, "house_fire: %d flame points, %d roof points", g_nhf, g_nrf); maplog("%s%s", t_, ""); }
    }
    if (g_nhf <= 0) return;
    for (int k = 0; k < 6; k++) { const float *e = g_hf[(k * 7) % g_nhf]; glow_add(e[0], e[1], e[3] + 0.6f, 3.6f); }      // the orange light on the garden
    float n = 70.0f * dt; while (n > 0.0f) {
        if (n >= 1.0f || frand() < n) { const float *e = g_hf[(int)(frand() * g_nhf) % g_nhf]; float z = e[2] + frand() * (e[3] - e[2]) * (frand() < 0.5f ? 1.0f : 0.15f); fire_spawn(e[0] + (frand() - 0.5f) * 0.5f, e[1] + (frand() - 0.5f) * 0.5f, z, 0.7f + frand() * 0.5f); }
        n -= 1.0f;
    }
    if (frand() < 8.0f * dt) { const float *e = g_hf[(int)(frand() * g_nhf) % g_nhf]; ember_spawn(e[0], e[1], e[3] + frand() * 2.0f, 0.7f); }
}
static void pan_path(char *out, size_t n, const char *map) { snprintf(out, n, "ux0:data/bbpsx/panels_%s.txt", map); }
