static const char *def_text(const char *const (*t)[2], const char *map) { for (int i = 0; t[i][0]; i++) if (!strcasecmp(t[i][0], map)) return t[i][1]; return NULL; }
static int pan_tex_resolve(const char *map, const char *name); static int pan_tex_ident(int tex, char *map, size_t mn, char *name, size_t nn);
static void pan_save(const char *map) {
    char p[160]; pan_path(p, sizeof p, map); FILE *f = fopen(p, "w"); if (!f) return;
    for (int i = 0; i < g_npan; i++) { char m_[48], n_[64]; const Panel *P = &g_pan[i]; fprintf(f, "%.3f %.3f %.3f %.3f %.3f %.4f", P->x, P->y, P->z, P->w, P->h, P->yaw);
        if (P->tex >= 0 && pan_tex_ident(P->tex, m_, sizeof m_, n_, sizeof n_)) fprintf(f, " -2 %s %s\n", m_, n_); else fprintf(f, " %d\n", P->tex >= 0 ? P->tex : -1); }
    fclose(f);
}
static void pan_parse(const char *ln) {
    if (g_npan >= PAN_MAX) return; Panel q; int tx = -1; char m_[48], n_[64]; int c = sscanf(ln, "%f %f %f %f %f %f %d %47s %63s", &q.x, &q.y, &q.z, &q.w, &q.h, &q.yaw, &tx, m_, n_);
    if (c < 6) return; q.tex = -1; if (c >= 7) { if (tx == -2 && c >= 9) q.tex = pan_tex_resolve(m_, n_); else if (tx >= 0 && tx < (int)nTex) q.tex = tx; }
    g_pan[g_npan++] = q;
}
static void pan_load(const char *map) {
    g_npan = 0; g_pan_sel = 0; char p[160]; pan_path(p, sizeof p, map); FILE *f = fopen(p, "r");
    if (f) { char ln[200]; while (fgets(ln, sizeof ln, f)) pan_parse(ln); fclose(f); return; }
    const char *d = def_text(PAN_DEF, map); if (!d) return;      // no file on the card: the panels baked into the game
    while (*d) { char ln[200]; size_t n = 0; while (*d && *d != '\n' && n < sizeof ln - 1) ln[n++] = *d++; ln[n] = 0; if (*d == '\n') d++; pan_parse(ln); }
}

