        static const char *th[4] = { "Table1HurtF1", "Table1HurtF2", "Table1HurtL1", "Table1HurtR1" }, *fh[4] = { "FreeHurt1", "FreeHurt2", "FreeHurtB1", "FreeHurtB2" };
        for (int k = 0; k < 4; k++) { int a = cpick(C, ph == 4 ? th[k] : fh[k]); if (a >= 0) P->hurt[P->nhurt++] = a; }
        P->counter = cpick(C, "Countered"); P->visc = cpick(C, "Visceraled"); P->death = cpick(C, "Death"); P->mbox = -1;
        P->trans = ph == 4 ? (cpick(C, "TableBreakFree") >= 0 ? cpick(C, "TableBreakFree") : cpick(C, "TableBreakFree2")) : -1; P->trans2 = -1; P->w_closed = P->w_open = P->w_unfold = -1;
        P->runv = ph == 4 ? 0.0f : (P->run >= 0 ? anim_speed(C, P->run, 3.2f) : 3.2f) * 1.15f;
        P->bod = 1.0f; P->hrad = 0.7f; P->zlo = 0.0f; P->zhi = 2.2f; P->cz = 1.3f;
