            static float pv_[3][3], pst_ = -1.0f; static const Enemy *pe_ = NULL; float cur_[3][3], l_[3], sc_ = ENEMY.scale > 0.0f ? ENEMY.scale : 1.0f; int hit_ = 0, any_ = 0;
            for (int k_ = 0; k_ < 3; k_++) cb_att_w(k_, cur_[k_]);
