    if (!ghh && !gbf) { g_gh_chain = 0; g_gh_punish = 0.0f; g_gh_atkn = 0; g_pl_heal_go = g_pl_shot_go = g_pl_atk_go = 0; for (int q_ = 0; q_ < 4; q_++) g_ghf[q_].t = 0.0f; }
