static int g_bs_elem = 0; static float g_bs_acc = 0.0f;      // new game plus: the Cleric Beast, Gascoigne's beast and Beast Gilbert each fight with a random power - 1 embers (fire), 2 sparks (lightning)
static int bs_elem_ok(void) {
    if (BS.idx < 0 || BS.idx >= n_en || !BS.fight || BS.sub == SUB_DEAD) return 0;
    Enemy *b = &ENS[BS.idx]; if (b->type != 4 || b->state == E_DEAD) return 0;
    if (cb_map() || gb_map()) return 1;
    return !strcasecmp(cur_map, "gascoignearena") && BS.phase >= 2;
}
static void bs_elem_tick(float dt) {
    if (g_ng <= 0 || !bs_elem_ok()) { g_bs_elem = 0; return; }
    Enemy *b = &ENS[BS.idx];
    if (!g_bs_elem) { g_bs_elem = 1 + (frand() < 0.5f); say(g_bs_elem == 1 ? "EMBERS CLING TO THE BEAST" : "THE BEAST CRACKLES WITH LIGHTNING"); }
    g_bs_acc += dt * (g_bs_elem == 1 ? 22.0f : 30.0f);
    while (g_bs_acc >= 1.0f) {
        g_bs_acc -= 1.0f; float a = frand() * 6.2832f, rr = 0.3f + frand() * 0.9f, z = b->p.z + b->cz * (0.15f + frand() * 1.5f);
        float x = b->p.x + cosf(a) * rr, y = b->p.y + sinf(a) * rr;
        if (g_bs_elem == 1) { ember_spawn(x, y, z, 0.45f); if (frand() < 0.3f) fire_spawn_short(x, y, z, 0.3f); } else spark_spawn(x, y, z, 0.2f);
    }
}
static float bs_elem_dmg(void) { return g_bs_elem ? 1.25f : 1.0f; }      // what the power adds to the damage he deals
