        char tc_[64]; { int k_ = 0, up_ = 1; for (const char *q_ = items[i]; *q_ && k_ < 62; q_++) { char c_ = *q_; if (c_ >= 'A' && c_ <= 'Z') c_ = up_ ? c_ : (char)(c_ + 32); up_ = (c_ == ' ' || c_ == '-'); tc_[k_++] = c_; } tc_[k_] = 0; }
        float tw_ = fb_run(tc_, 0, 0, cap_, 0, 0, 0, 0, 0);
