                FILE *wf_ = fopen("ux0:data/bbpsx/wheelchair.txt", "w"); if (wf_) { fprintf(wf_, "%.2f %.2f %.1f\n", g_wc_t[0], g_wc_t[1], g_wc_t[2]); fclose(wf_); }
                char t_[72]; snprintf(t_, sizeof t_, "CHAIR  FWD %.1f  LEFT %.1f  TURN %.0f", g_wc_t[0], g_wc_t[1], g_wc_t[2]); say(t_);
