            if (ch_ == 2) { const float *p_ = md_ == 0 ? g_gh_boff : &g_wadj[md_ == 1 ? 0 : 3]; char t_[96]; snprintf(t_, sizeof t_, "%s  %c  %+.1f   (X %+.1f  Y %+.1f  Z %+.1f)", md_ == 0 ? "BLADE" : (md_ == 1 ? "GRIP SLIDE CM" : "GRIP TURN DEG"), "XYZ"[ax_], p_[ax_], p_[0], p_[1], p_[2]); say(t_); ch_ = 0; }
            if (pressed & SCE_CTRL_TRIANGLE) { g_gh_half = f_; FILE *wf_ = fopen("ux0:data/bbpsx/gh_half.txt", "w"); if (wf_) { fprintf(wf_, "%.3f %.2f %.2f %.2f %.2f %.2f %.2f %.1f %.1f %.1f\n", f_, g_gh_boff[0], g_gh_boff[1], g_gh_boff[2], g_wadj[0], g_wadj[1], g_wadj[2], g_wadj[3], g_wadj[4], g_wadj[5]); fclose(wf_); } char t_[64]; snprintf(t_, sizeof t_, "SPEAR  %.2f  SAVED", f_); say(t_); ch_ = 0; }
            else if (ch_) { char t_[64]; snprintf(t_, sizeof t_, "SPEAR  %.2f  %s", f_, play_ ? "PLAYING" : "PAUSED"); say(t_); ch_ = play_; }
