                if (g_pe_mode == 0) { float hl_ = sqrtf(fx * fx + fy * fy); if (hl_ < 1e-3f) hl_ = 1.0f; P->x += (fx / hl_ * fwd + rx * str) * sp_; P->y += (fy / hl_ * fwd + ry * str) * sp_; P->z += vz_ * sp_; }
