            if (g_npan > 0) { const Panel *P = &g_pan[g_pan_sel]; snprintf(g_pe_txt, sizeof g_pe_txt, g_pe_mode == 3 ? "PANEL %d/%d  TEXTURE  %s  UP NEXT  O PREVIOUS" : "PANEL %d/%d  %s  W %.1f H %.1f  Z %.1f", g_pan_sel + 1, g_npan, g_pe_mode == 3 ? ((P->tex >= 0 && P->tex < (int)nTex && texNm) ? texNm[P->tex] : "BLACK") : MN_[g_pe_mode], P->w, P->h, P->z); }
            else snprintf(g_pe_txt, sizeof g_pe_txt, "NO PANELS  TRIANGLE ADDS ONE  SQUARE: %s", MN_[g_pe_mode]);
